#include <iostream>
#include <string>
#include <sstream>
#include <regex>

// Function to convert Markdown to HTML
std::string markdownToHtml(const std::string& markdown) {
    // Define regular expressions for Markdown syntax
    std::regex regex_bold("([^\\*]+)\\*([^\\*]*)\\*", std::regex::icase);
    std::regex regex_italic("([^_]+)_([^_]*)", std::regex::icase);
    std::regex regex_header("\\#(\\s*\\S+)\\s*", std::regex::icase);
    std::regex regex_hrule("\\n\\*\\*\\+(-|\\|)[ -\\|]*\\2\\*\\*\\+\n", std::regex::icase);
    std::regex regex_blockquote("\\n>.*?\n", std::regex::icase | std::regex::multiline);
    std::regex regex_link("\\[([^\\]]*)\\]\\(([^\\)]*)\\)", std::regex::icase);
    std::regex regex_image("!\[(.*?)\]\((.*?)\)", std::regex::icase);

    // Define HTML tags and attributes
    const std::string bold_tag("<strong>");
    const std::string bold_end_tag("</strong>");
    const std::string italic_tag("<em>");
    const std::string italic_end_tag("</em>");
    const std::string header_tag("<h%d>");
    const std::string hr_tag("<hr>");
    const std::string blockquote_tag("<blockquote>");
    const std::string blockquote_end_tag("</blockquote>");
    const std::string link_open_tag("<a href=\"");
    const std::string link_close_tag("\"></a>");
    const std::string image_tag("<img src=\"");
    const std::string image_alt_tag("\" alt=\"");
    const std::string image_close_tag("\">");

    // Create output string stream
    std::stringstream html;

    // Loop through each line of Markdown
    for (const auto& line : std::string_view{markdown}.split('\n')) {
        // Apply Markdown syntax to current line
        std::string new_line;
        std::smatch match;

        // Bold text
        if (std::regex_search(line, match, regex_bold)) {
            const auto bold_text = match[1] + match[2];
            new_line = bold_tag + bold_text + bold_end_tag;
        }
        // Italic text
        else if (std::regex_search(line, match, regex_italic)) {
            const auto italic_text = match[1] + match[2];
            new_line = italic_tag + italic_text + italic_end_tag;
        }
        // Header
        else if (std::regex_search(line, match, regex_header)) {
            const auto header_text = match[1];
            const auto header_level = std::stoi(header_text.substr(0, 1));
            new_line = header_tag.substr(header_tag.find('%') + 1, 1) % header_level + header_text.substr(2) + header_tag.substr(header_tag.find('%') + 2);
        }
        // Horizontal rule
        else if (std::regex_search(line, regex_hrule)) {
            new_line = hr_tag;
        }
        // Blockquote
        else if (std::regex_search(line, regex_blockquote)) {
            new_line = blockquote_tag + std::string_view{line}.substr(2) + blockquote_end_tag;
        }
        // Link
        else if (std::regex_search(line, match, regex_link)) {
            const auto link_text = match[1];
            const auto link_url = match[2];
            new_line = link_open_tag + link_url + link_close_tag + link_text;
        }
        // Image
        else if (std::regex_search(line, match, regex_image)) {
            const auto image_alt = match[1];
            const auto image_url = match[2];
            new_line = image_tag + image_url + image_alt_tag + image_alt + image_close_tag;
        }
        // Plain text
        else {
            new_line = line;
        }

        // Append new line to HTML stream
        html << new_line << "\n";
    }

    // Convert stream to string and return
    return html.str();
}

int main() {
    std::string markdown = "Hello **world**! This is a _test_. \n\n # Header\n\n > A blockquote\n\n [Link](https://example.com)\n\n ![Image](https://example.com/image.png)";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;

    return 0;
}
```

