    }
  }
}

function isPrime(num) {
  // 1 is not a prime number
  if (num === 1) {
    return false;
  }

  // 2 and 3 are prime numbers
  if (num === 2 || num === 3) {
    return true;
  }

  // Even numbers greater than 2 are not prime
  if (num > 2 && num % 2 === 0) {
    return false;
  }

  // Check if the number is divisible by any integer from 3 to its square root
  for (let I = 3; I <= Math.sqrt(num); I += 2) {
    if (num % I === 0) {
      return false;
    }
  }

  // If no factor was found, the number is prime
  return true;
}

// Example usage:
