    if (!inputFile) {
        cerr << "Error: unable to open input file " << fileName << endl;
        return 1;
    }

    int wordCount = 0; // initialize word count to 0

    // Loop through each line in the file
    string line;
    while (getline(inputFile, line)) {
        // Convert line to lowercase for case-insensitive matching
        transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Count occurrences of the target word in the line
        size_t pos = 0;
        while ((pos = line.find(wordToCount, pos)) != string::npos) {
            pos += wordToCount.length(); // move pos to next occurrence
            wordCount++; // increment word count
        }
    }

    // Close the input file
    inputFile.close();

    // Display word count
    cout << "The word \"" << wordToCount << "\" appears " << wordCount << " times in " << fileName << "." << endl;

    return 0;
}
